INSERT INTO public.conditions VALUES ('rules-general', 'Nội quy Homestay', 'Các quy định về giờ giấc (sau 23h hạn chế làm ồn), vệ sinh chung và tiếp khách ngoài.', true, '2026-07-05 08:06:56.103+00');
INSERT INTO public.conditions VALUES ('rules-deposit', 'Quy định hoàn cọc', 'Cần báo trước ít nhất 30 ngày trước khi chuyển đi để được hoàn 100% tiền cọc.', true, '2026-07-05 08:06:56.106+00');
INSERT INTO public.conditions VALUES ('rules-service', 'Quy định thanh toán', 'Hóa đơn tiền phòng và dịch vụ phát sinh đầu tháng phải được thanh toán trước ngày 5 hàng tháng.', true, '2026-07-05 08:06:56.106+00');
INSERT INTO public.conditions VALUES ('cond-luutru-1', 'Điều kiện nhận phòng lưu trú', 'Yêu cầu xuất trình CMND/CCCD hoặc Hộ chiếu bản gốc còn hiệu lực khi tiến hành thủ tục nhận phòng lưu trú.', true, '2026-07-14 20:35:34.339494+00');
INSERT INTO public.conditions VALUES ('cond-luutru-2', 'Quy định trả phòng lưu trú', 'Thời gian trả phòng muộn nhất là 12h00 trưa. Việc trả phòng trễ sẽ bị tính thêm phụ phí lưu trú theo bảng giá hiện hành.', true, '2026-07-14 20:35:34.339494+00');
INSERT INTO public.conditions VALUES ('cond-luutru-3', 'Giờ giới nghiêm lưu trú', 'Khách lưu trú không được ra vào khu vực toà nhà sau 23h30 để đảm bảo an ninh và giấc ngủ cho các phòng lân cận.', true, '2026-07-14 20:35:34.339494+00');
INSERT INTO public.conditions VALUES ('cond-luutru-4', 'Đăng ký khách ngoài lưu trú qua đêm', 'Khách đến chơi không được tự ý ngủ lại qua đêm. Phải đăng ký trước với Ban quản lý và nộp phụ phí lưu trú (áp dụng tối đa 2 đêm/tháng).', true, '2026-07-14 20:35:34.339494+00');
INSERT INTO public.conditions VALUES ('cond-luutru-5', 'Điều kiện chuyển phòng lưu trú', 'Nếu có nhu cầu chuyển sang phòng khác trong cùng hệ thống, khách lưu trú phải thông báo bằng văn bản trước ít nhất 15 ngày.', true, '2026-07-14 20:35:34.339494+00');


